// One Publish-to channel for a group.
import React from 'react';
import { View } from 'react-native';
import { Stack, useLocalSearchParams } from 'expo-router';
import { BackChevron, EmptyState, Page } from '../../../../components/ui';
import { NotFound, useCanModerate } from '../../../../components/mod';
import { GroupPublishScreen } from '../../../../components/group-publish';

export default function GroupPublishRoute() {
  const params = useLocalSearchParams<{ id: string; channel: string }>();
  const id = Array.isArray(params.id) ? params.id[0] : params.id;
  const channel = Array.isArray(params.channel) ? params.channel[0] : params.channel;
  const { ready, ok } = useCanModerate();
  const backFallback = id ? `/groups/${id}` : '/groups';
  let body: React.ReactNode;
  if (!ready) body = <Page scroll={false} fill><BackChevron fallback={backFallback} /><View style={{ flex: 1 }} /></Page>;
  else if (!ok) body = <Page><BackChevron fallback="/groups" /><NotFound /></Page>;
  else if (!id || !channel) body = <Page><BackChevron fallback={backFallback} /><EmptyState title="Channel not found" /></Page>;
  else body = <GroupPublishScreen groupId={id} channel={decodeURIComponent(channel)} />;
  return (
    <>
      <Stack.Screen options={{ headerShown: false }} />
      {body}
    </>
  );
}
